"""Demo: first moment of fixed points equals n! for every n >= 1.

Enumerates all n! permutations of {0,...,n-1}, sums the number of fixed points,
and confirms the total is exactly n!, so the average is exactly 1.
"""
from __future__ import annotations
from itertools import permutations
from math import factorial


def total_fixed_points(n: int) -> int:
    return sum(
        sum(1 for i, s in enumerate(sigma) if s == i)
        for sigma in permutations(range(n))
    )


def main() -> None:
    for n in range(1, 8):
        total = total_fixed_points(n)
        assert total == factorial(n)
        print(f"n={n}: total fixed points = {total} = {n}!  "
              f"expected #fixed = {total / factorial(n):.4f}")


if __name__ == "__main__":
    main()

"""Demo: expected number of roots of a random monic polynomial over F_q is 1.

Enumerates all q^n monic degree-n polynomials over F_q = Z/qZ (q prime),
counts roots, and confirms the total is exactly q^n.
"""
from __future__ import annotations
from itertools import product


def monic_eval(coeffs: tuple[int, ...], r: int, q: int, n: int) -> int:
    value = pow(r, n, q)
    for i, c in enumerate(coeffs):
        value = (value + c * pow(r, i, q)) % q
    return value


def total_root_incidences(q: int, n: int) -> int:
    return sum(
        sum(1 for r in range(q) if monic_eval(coeffs, r, q, n) == 0)
        for coeffs in product(range(q), repeat=n)
    )


def main() -> None:
    for q, n in [(2, 2), (3, 2), (5, 2), (2, 3), (3, 3), (7, 2)]:
        total = total_root_incidences(q, n)
        assert total == q ** n
        print(f"q={q}, n={n}: total roots = {total} = q^n  "
              f"expected #roots = {total / q ** n:.4f}")


if __name__ == "__main__":
    main()

"""Demo: the 1/n law -- probability a random permutation is an n-cycle is 1/n.

Counts n-cycles in S_n by enumeration and checks the count equals (n-1)!,
so the probability equals (n-1)!/n! = 1/n.
"""
from __future__ import annotations
from itertools import permutations
from math import factorial


def is_n_cycle(sigma: tuple[int, ...]) -> bool:
    n = len(sigma)
    if n == 0:
        return False
    j, seen = 0, 0
    while True:
        j = sigma[j]
        seen += 1
        if j == 0:
            break
    return seen == n


def count_n_cycles(n: int) -> int:
    return sum(1 for s in permutations(range(n)) if is_n_cycle(s))


def main() -> None:
    for n in range(2, 8):
        c = count_n_cycles(n)
        assert c == factorial(n - 1)
        print(f"n={n}: #n-cycles = {c} = (n-1)!  P(n-cycle) = {c / factorial(n):.5f}"
              f"  (1/n = {1 / n:.5f})")


if __name__ == "__main__":
    main()

