"""Visualization: proportion of irreducible monic polynomials over F_q
converging to the combinatorial value 1/n as q grows."""
import matplotlib.pyplot as plt


def irreducible_count(q: int, n: int) -> int:
    from itertools import product

    def poly_mod(dividend, divisor):
        rem = dividend[:]
        dd = len(divisor) - 1
        while len(rem) - 1 >= dd:
            while rem and rem[-1] % q == 0:
                rem.pop()
            if len(rem) - 1 < dd:
                break
            lead, shift = rem[-1], len(rem) - 1 - dd
            for i, c in enumerate(divisor):
                rem[i + shift] = (rem[i + shift] - lead * c) % q
        return all(c % q == 0 for c in rem)

    def irreducibles(deg):
        out = []
        for coeffs in product(range(q), repeat=deg):
            poly = list(coeffs) + [1]
            if deg == 1:
                out.append(poly)
                continue
            red = any(poly_mod(poly, lo) for d in range(1, deg)
                      for lo in irreducibles(d))
            if not red:
                out.append(poly)
        return out

    return len(irreducibles(n))


def main() -> None:
    qs = [2, 3, 5, 7, 11, 13]
    fig, ax = plt.subplots(figsize=(8, 5))
    for n, color in [(2, "tab:blue"), (3, "tab:red")]:
        props = [irreducible_count(q, n) / q ** n for q in qs]
        ax.plot(qs, props, "o-", color=color, label=f"degree n={n}")
        ax.axhline(1 / n, color=color, ls="--", alpha=0.6, label=f"1/{n}")
    ax.set_xlabel("field size q")
    ax.set_ylabel("proportion irreducible")
    ax.set_title("Proportion of irreducibles -> 1/n (the n-cycle fraction)")
    ax.legend()
    fig.tight_layout()
    fig.savefig("irreducible_convergence.png", dpi=150)
    print("saved irreducible_convergence.png")


if __name__ == "__main__":
    main()
